import requests
import os
from msal import ConfidentialClientApplication

AZURE_TENANT_ID = os.getenv("AZURE_TENANT_ID")
AZURE_CLIENT_ID = os.getenv("AZURE_CLIENT_ID")
AZURE_CLIENT_SECRET = os.getenv("AZURE_CLIENT_SECRET")

AUTHORITY = f"https://login.microsoftonline.com/{AZURE_TENANT_ID}"
CLIENT_APP = ConfidentialClientApplication(
    AZURE_CLIENT_ID,
    authority=AUTHORITY,
    client_credential=AZURE_CLIENT_SECRET
)

def get_user_profile(access_token):
    GRAPH_ENDPOINT = "https://graph.microsoft.com/v1.0/me"
    headers = {
        "Authorization": f"Bearer {access_token}",
        "Accept": "application/json"
    }
    response = requests.get(GRAPH_ENDPOINT, headers=headers)
    response.raise_for_status()
    return response.json()

def federated_login_flow(authorization_code, redirect_uri):
    token_response = CLIENT_APP.acquire_token_by_authorization_code(
        authorization_code,
        scopes=["User.Read"],
        redirect_uri=redirect_uri
    )
    if "access_token" in token_response:
        user_profile = get_user_profile(token_response["access_token"])
        return {
            "user_id": user_profile.get("id"),
            "email": user_profile.get("mail"),
            "display_name": user_profile.get("displayName")
        }
    else:
        raise ValueError("Token acquisition failed")
